const {realVar, vectorVar, vec} = Symbolic;
const {fitData} = DataScience;
let input = Array.range(0, 500).map(i => [2*Math.random()-1, 2*Math.random()-1])
let yf = ([x, y]) => 2*x*x - y*y + x*y + 0.5 + 0.3*(2*Math.random()-1)
let {scene} = IO.plotPointCloud(input.map(([x,y]) => [x, y, yf([x,y])]))
let x = realVar("x", true)
let y = realVar("y", true)
let a = vectorVar("a", 6)
let f = vec(1, x, y, x.mul(x), x.mul(y), y.mul(y)).dot(a)
const { compiledModel, theta} = fitData(input, input.map(p => yf(p)), f, {epochs: 2000, batch: 20})
IO.plotPointCloud(input.map(([xi,yi]) => [xi, yi, compiledModel({x: xi, y: yi, ...theta})]), {scene, color:[0,0,1]})
